import React from "react";

// Reusable balance summary card — used on the Wallet page and could be
// dropped onto the Dashboard's quick-actions row if a balance preview
// is ever needed there.
export default function WalletCard({ balance, currency, onAddFunds, onPay }) {
  return (
    <div className="wallet-balance-card">
      <div className="wallet-balance-label">Available balance</div>
      <div className="wallet-balance-amount">
        {currency} {balance.toFixed(2)}
      </div>
      <div className="wallet-actions">
        <button className="btn btn-lime btn-sm" onClick={onAddFunds}>Add funds</button>
        <button className="btn btn-ghost btn-sm" onClick={onPay}>Simulate payment</button>
      </div>
    </div>
  );
}
